using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer.Tools;

[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the DI container provides HttpClient automatically
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city")]
    public async Task<string> GetWeather(
        [Description("City name, e.g. 'London'")] string city,
        [Description("Units: 'metric' or 'imperial'")] string units = "metric")
    {
        var response = await _httpClient.GetFromJsonAsync<WeatherResponse>(
            $"/weather?q={Uri.EscapeDataString(city)}&units={units}");

        if (response is null)
            return $"No weather data found for '{city}'.";

        return $"{city}: {response.Description}, {response.Temperature}°{(units == "metric" ? "C" : "F")}";
    }

    [McpServerTool, Description("Get a 5-day weather forecast for a city")]
    public async Task<string> GetForecast(
        [Description("City name")] string city)
    {
        var response = await _httpClient.GetAsync(
            $"/forecast?q={Uri.EscapeDataString(city)}&units=metric");

        if (!response.IsSuccessStatusCode)
            return $"Failed to retrieve forecast for '{city}': {response.StatusCode}";

        var content = await response.Content.ReadAsStringAsync();
        return content;
    }
}

public record WeatherResponse
{
    [JsonPropertyName("temp")]
    public double Temperature { get; init; }

    [JsonPropertyName("description")]
    public string Description { get; init; } = "";
}

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using McpServer.Tools;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

// Register a named HttpClient for WeatherTools — the MCP SDK resolves it via DI
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.BaseAddress = new Uri("https://api.example.com/v1");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

var app = builder.Build();
await app.RunAsync();

